//! This module is responsible for providing the interface for fetching the command signatures.
//! It abstracts away the underlying directory hierarchy. We organize the command signatures to
//! keep autogenerated specs separate from hand-written ones. However, the caller shouldn't need to
//! know that detail, and so we use this module to "flatten" the contents of
//! json/autogenerated/**/*.json and present an API to lookup command signatures by name only.
//!
//! `build.rs` deflates every spec into one embedded blob (json/*.json first, then
//! json/autogenerated/powershell/*.json); a lookup inflates just the file it asks for.
use std::borrow::Cow;
use std::io::Read as _;

mod index {
    include!(concat!(env!("OUT_DIR"), "/signatures_index.rs"));
}

static BLOB: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/signatures.deflate"));

/// The hand-written specs (json/*.json; autogenerated/ and overrides/ are left out), then the
/// autogenerated PowerShell specs. Each table is sorted by file name.
const TABLES: [&[(&str, usize, usize)]; 2] = [index::MANUAL, index::POWERSHELL];

/// Provides a single namespace for accessing command signatures by file name (`git.json`),
/// abstracting away the underlying directory hierarchy.
pub(super) struct Assets;

impl Assets {
    /// Returns the JSON for `file_path` (e.g. `git.json`), preferring a hand-written spec over
    /// an autogenerated one of the same name.
    pub(super) fn get(file_path: &str) -> Option<Vec<u8>> {
        TABLES.iter().find_map(|table| {
            let index = table
                .binary_search_by(|(name, _, _)| (*name).cmp(file_path))
                .ok()?;
            let (_, offset, len) = table[index];
            let mut json = Vec::new();
            flate2::read::DeflateDecoder::new(&BLOB[offset..offset + len])
                .read_to_end(&mut json)
                .ok()?;
            Some(json)
        })
    }

    pub(super) fn iter() -> impl Iterator<Item = Cow<'static, str>> {
        Self::names().map(Cow::Borrowed)
    }

    pub(super) fn names() -> impl Iterator<Item = &'static str> {
        TABLES
            .into_iter()
            .flat_map(|table| table.iter().map(|(name, _, _)| *name))
    }
}

/// Iterates over the names of all known command signatures.
#[cfg(test)]
pub(super) fn all_signature_names() -> impl Iterator<Item = &'static str> {
    Assets::names().filter_map(|name| name.strip_suffix(".json"))
}
